// naive matcher: returns "match" (method matches), "mismatch" (path matches, method not), "none"
func naive(routes map[string]string, method, path string) string {
	pathMatch := false
	methodMatch := false
	for p, m := range routes {
		if matchPattern(p, path) {
			pathMatch = true
			if m == method {
				methodMatch = true
			}
		}
	}
	if methodMatch {
		return "match"
	}
	if pathMatch {
		return "mismatch"
	}
	return "none"
}

func matchPattern(pattern, path string) bool {
	// pattern like /a/:b/* ; "*" matches remainder (possibly empty after slash)
	ps := strings.Split(pattern, "/")
	xs := strings.Split(path, "/")
	i := 0
	for ; i < len(ps); i++ {
		if ps[i] == "*" {
			return true
		}
		if i >= len(xs) {
			return false
		}
		if strings.HasPrefix(ps[i], ":") {
			continue
		}
		if ps[i] != xs[i] {
			return false
		}
	}
	return len(xs) == len(ps)
}

